    var R=(book==='SPXW')?tapeReadSPXW(today):tapeReadTrinity(book); if(!R) return;
    var rec={ id:today+'|'+book+'|'+bar, day:today, book:book, bar:bar, t:t||Date.now(), px:px, n:R.n, rows:R.rows };
    if(book==='SPXW'){ rec.ts=R.ts||null; } else { rec.king=R.king; rec.kd=R.kd; }
    var B=tapeBook(book); B.bars=B.bars.filter(function(b){ return b.bar!==bar; }); B.bars.push(rec); if(B.bars.length>TAPE_MAX_BARS) B.bars=B.bars.slice(-TAPE_MAX_BARS);
