function tapePruneDay(day){ try{ repoOpen(function(db){ if(!db) return; try{ var st=db.transaction('tape','readwrite').objectStore('tape'); var ix=st.index('day'); ix.openKeyCursor(IDBKeyRange.only(day)).onsuccess=function(e){ var c=e.target.result; if(c){ st.delete(c.primaryKey); c.continue(); } }; }catch(e){} }); }catch(e0){} }
