function tapeHealth(){ var o={ day:TAPE.day, restored:TAPE._restored, lastWrite:TAPE_LAST_WRITE, books:{} }; Object.keys(TAPE.books).forEach(function(b){ var B=TAPE.books[b]; var last=B.bars[B.bars.length-1]; o.books[b]={ bars:B.bars.length, strikesLast:last?last.n:0, lastBar:last?last.bar:null }; }); return o; }
