var DAY_WRITTEN={};
var DATA_DIR_H=null;
var REPO_AUTO_TRIED=null;
// 08:30–15:00 CT on a weekday: the session. No rule writes inside it; a clock fault reads as market hours (the safe side).
function ctMarketHours(){ try{ var d=ctNow(); var wd=d.getDay(); if(wd===0 || wd===6) return false; var s=ctNowSecOfDay(); return s>=8*3600+30*60 && s<15*3600; }catch(e){ return true; } }
