function ctAfterClose(){ try{ var d=ctNow(); var wd=d.getDay(); if(wd===0 || wd===6) return false; return ctNowSecOfDay()>=15*3600+60; }catch(e){ return false; } }
function dayWrittenMark(date, how, by){ DAY_WRITTEN[date]={ t:Date.now(), how:how, by:by||null }; try{ repoKvSet('dayWritten:'+date, DAY_WRITTEN[date]); }catch(e){} }
