  try{ if(DATA_DIR_H && DATA_DIR_H.requestPermission){ DATA_DIR_H.requestPermission({mode:'readwrite'}).then(function(p){ AUTOSAVE.perm=p; if(p==='granted') AUTOSAVE.blocked=null; go(); }, function(){ go(); }); return; } }catch(e0){}
