// ---- DAILY ARCHIVE EXPORT (v10.15) -----------------------------------------
// Build a self-describing export payload for ONE trading day (default today):
// the labeled snapshot vectors + outcome events + a small header so the
// end-of-day LLM review knows the schema without guessing. This is what gets
// dropped into AI Drive /GEX-Signal-Tapereader/daily-data/ for the scheduled
// review workflow to consume.
// ============================================================================
// (v10.55 PART F) ENGINE-READY DATA. The day export already carried every feature
// record and every resolved outcome — but as a per-feature queue, which is not a
// shape any model can read. `matrix` is ONE ROW PER BAR PER SYMBOL: every recorded
// vote / grade / input flattened into `feature.field` columns, the regime, session
// and model stamp beside them, and the four labels (dirHit, deflHit, contHit,
// tgtHit) plus MFE/MAE at the end. CSV is one map() away; so is a model.
// ============================================================================
function buildFeatureMatrix(day){
  var rows=[];
  try{
    var feat=(day&&day.feat)||{};
    Object.keys(feat).forEach(function(sym){
      var byBar={}, order=[];
      (feat[sym]||[]).forEach(function(r){
        if(!r || typeof r.bar!=='number') return;
        var id=sym+'|'+r.bar;
        var row=byBar[id];
        if(!row){
          row=byBar[id]={ sym:sym, bar:r.bar, t:r.t||null, n:(r.n!=null?r.n:null), px:(r.px!=null?r.px:null),
                          session:r.session||null, regime:null, opex:null, event:null,
                          rulesAsOf:null, weightsHash:null,
                          dirHit:null, deflHit:null, contHit:null, tgtHit:null, mfe:null, mae:null, partial:null };
          order.push(id);
        }
        var rec=r.rec||{};
        Object.keys(rec).forEach(function(f){
          var v=rec[f];
          if(v && typeof v==='object'){
            if(f==='regime'){ row.regime=v.tag||null; row.opex=!!v.opex; row.event=(v.event===true)?1:0; }
            else if(f==='model'){ row.rulesAsOf=v.rulesAsOf||null; row.weightsHash=v.weightsHash||null; }
            else if(!(v instanceof Array)){
              Object.keys(v).forEach(function(f2){ var v2=v[f2];
                if(v2==null || typeof v2!=='object') row[r.key+'.'+f+'.'+f2]=v2; });
            }
            return;
          }
          row[r.key+'.'+f]=v;
        });
        // ---- the four labels ----
        if(r.key==='dir'){
          row.dirHit=(r.hit!=null)?r.hit:null;
          row.mfe=(r.mfe!=null)?r.mfe:row.mfe; row.mae=(r.mae!=null)?r.mae:row.mae;
          row.partial=r.partial?1:0;
          if(r.frame) row.tgtHit=(r.frame.first==='tgt')?1:((r.frame.first==='inval')?0:null);
        }
        if(r.key==='node'  && r.hit!=null) row.deflHit=r.hit;
        if(r.key==='leg.pbDetect' && r.hit!=null && row.deflHit==null) row.deflHit=r.hit;
        if(r.key==='leg.roll' && r.hit!=null) row.contHit=r.hit;
        if(row.mfe==null && r.mfe!=null){ row.mfe=r.mfe; row.mae=r.mae; }
      });
      order.forEach(function(id){ rows.push(byBar[id]); });
    });
    rows.sort(function(a,b){ return (a.sym===b.sym) ? (a.bar-b.bar) : (a.sym<b.sym?-1:1); });
  }catch(e){}
  return rows;
}
// ⚠⚠ (v14.51) AN EXPORT MUST NEVER WRITE AN EMPTY DAY OVER A REAL ONE — AND IT DID.
// `dk = dateKey || TODAY` exported whatever calendar day it happened to be. Run before the open —
// 2026-08-26 at 01:56 ET — "today" was a day with no bars in it yet, so the file written was EMPTY
// and stamped with that date. Nothing ran again after the session, so the 182 snapshots and 59
// deflections that day actually recorded never reached a file, and the repo held an empty record
// that looked exactly like "nothing happened". A measurement programme that silently loses sessions
// cannot settle anything, and this one lost one while we were quoting statistics at each other.
// TWO GUARDS, because either alone would have failed here:
//   1. with no explicit date, export the most recent day that HAS DATA, not the wall-clock day;
//   2. refuse outright to build an export whose day is empty, and say so loudly.
function dayHasData(day){
  try{
    if(!day) return false;
    var n=0;
    ['snaps','events','feat','defl','pblog'].forEach(function(k){
      var v=day[k]; if(!v) return;
      if(Object.prototype.toString.call(v)==='[object Array]') n+=v.length;
      else if(typeof v==='object') for(var s in v){ if(Object.prototype.toString.call(v[s])==='[object Array]') n+=v[s].length; }
    });
    return n>0;
  }catch(e){ return false; }
}
function lastDayWithData(db){
  try{
    var ds=Object.keys((db&&db.days)||{}).sort();
    for(var i=ds.length-1;i>=0;i--) if(dayHasData(db.days[ds[i]])) return ds[i];
  }catch(e){}
  return null;
}
function buildDayExport(dateKey){
  var db=recorderLoad();
  var dk=dateKey || (dayHasData(db.days&&db.days[TODAY]) ? TODAY : (lastDayWithData(db)||TODAY));
  var day=(db.days&&db.days[dk])?db.days[dk]:{snaps:{},events:{}};
  if(!dayHasData(day)){
    // an empty export is worse than none: it overwrites a real record with a plausible-looking blank
    return { schema:'gex-day-export/v1', date:dk, empty:true, generatedAt:new Date().toISOString(),
             refused:'REFUSED — this day has no recorded bars. Exporting it would write an empty file that is indistinguishable from a completed session. Nothing was written.' };
  }
  return {
    schema:'gex-day-export/v1',
    // (v10.42) FEEDBACK LOOP payload: the projection scorecard + auto tuning
    // recommendations ride in the export so the end-of-day LLM review consumes
    // them with zero extra steps. proj per-bar records live in snaps[].proj.
    // (v15.53, D7) projReview REMOVED from the export: it scored `snap.proj`, produced by the projected
    // King chart that stopped rendering at v14 — the nightly was being handed scores for a dead surface.
    // (v10.54, audit 5) the export version was frozen at '10.15' for 39 releases, so no
    // consumer could tell which panel wrote a file. It is the real version now.
    version:VERSION_STR(),
    rulesAsOf:(function(){ try{ return (rulesDoc()||{}).asOf||null; }catch(eRa){ return null; } })(),
    model:(function(){ try{ return modelStamp(); }catch(eMs){ return null; } })(),
    effN:{ fwd:FEAT_FWD, note:'every feature record is one BAR; effective observations = n / fwd' },
    date:dk,
    generatedAt:new Date().toISOString(),
    horizons:{ out5:'5 bars = 15 min forward', out10:'10 bars = 30 min forward' },
    legend:{
      sig:'per-bar derived signal read: trend{state,up,win,ma,slope}, king{cls,word,drift,score,magnet,offK}, srb{dom,cross,supF,resF,supPct,floorK,floorFade,ceilK,ceilFade}, breadth{net,dir,mag}, conf{dir,word,score,aligned,bull,bear,declared}',
      out:'forward outcome {mfe:max up, mae:max down(<=0), net, pxEnd, hitKing, revUp, revDn, n}',
      nodeEvents:'one row per NODE EVENT (not per bar). ty: ROLL | ACCUM | DISSIP | TURN_UP | TURN_DN. '+
        'w = the why-vector AT THE INSTANT it fired: k, side, pct, role, dist, cur/d5/d15/d60/d1d (Skylit verbatim), '+
        'pull (OUR magnetism formula |value|/distance, NOT Skylit\'s - they give no equation), rg (regime), '+
        'trend, emPct, hhmm, taps, stage (Fresh/Tested/Delivered/Decaying), tapProb. '+
        'ROLL also carries to/toEs/toPct/got/lost/dir/toIsBiggest and wTo (the destination\'s why-vector). '+
        'o5/o10/o20 = outcome at 5/10/20 bars: {k: DEFLECT|PIN|BREAK|GRAZE|NOTOUCH, beyond, away, os:beachball}. '+
        'BOTH DEFLECT AND PIN ARE THE LEVEL WORKING - only BREAK is failure. A binary hold-rate scores '+
        'pinning as failure and produced a wrong result once already (FINDINGS F7/F8).'
    },
    syms:RECORDER_SYMS,
    snaps:day.snaps||{},
    events:day.events||{},
    // (v13.4) THE NODE EVENT LEDGER — rolls / accumulation / dissipation with their why-vector and
    // the three-way outcome (DEFLECT / PIN / BREAK) at 5, 10 and 20 bars. This is the row that makes
    // descriptive AND predictive analysis of rolls possible: a bar snapshot can only answer questions
    // about bars, and a roll is an event.
    nodeEvents:(function(){ try{ return nevDay().ev; }catch(e){ return []; } })(),
    // (v10.49 B/H) the feature-registry layer: per-bar records under snaps[].feat, the
    // resolved outcome queue here, plus the operator's take/pass log.
    feat:day.feat||{},
    defl:day.defl||{},           // (v15.54) the EVENT-level deflection ledger — what H5 is scored on
    requests:(function(){ try{ return requestsExport(dk); }catch(eRq){ return []; } })(),   // (v15.55) what he asked to be tracked — the nightly copies it to learning/requests.json
    items:(function(){ try{ return itemsExport(dk); }catch(eIt){ return []; } })(),         // (v15.60) issues · questions · enhancement requests — the nightly copies them to learning/items.json
    reco:(function(){ try{ return recoExport(dk); }catch(eRc){ return {}; } })(),           // (v15.70) his ✓ / ✗ on the Rec tab — the nightly sets the rows' status in learning/recommendations.json
    act:day.act||{},
    // (v10.55 PART F) the same records, ENGINE-READY: one row per bar per symbol.
    matrix:(function(){ try{ return buildFeatureMatrix(day); }catch(eMx){ return []; } })(),
    matrixLegend:'one row per (sym, bar); columns are feature.field of every recorded input/vote plus regime/session/model; labels dirHit (direction travelled DIR_PTS), deflHit (node/pullback held), contHit (roll continued), tgtHit (frame target before invalidation), with MFE/MAE',
    // (v10.55 PART A/D) the per-bar node-cluster history the leg engine reads, and the
    // multi-session rolling read derived from FCHIST.
    // (v15.53) nodeHist left the export with NODEHIST (H-write-only)
    // (v11.0) THE NODE LEDGER — every node's life, touches, reactions, influence (layer 1)
    ledger:(function(){ try{ var o={}; RECORDER_SYMS.forEach(function(s){ o[s]=ledgerExport(s); }); return o; }catch(eLd){ return null; } })(),
    sessionRoll:(function(){ try{ var o={}; RECORDER_SYMS.forEach(function(s){ o[s]=sessionRoll(s); }); return o; }catch(eSr){ return null; } })(),
    // (v14.59) the HOD/LOD corpus feed - raw courier bars, bucketed downstream by tools/append-futures.py
    futBars:(function(){ try{ return futBarsLoad(); }catch(eFb){ return null; } })(),
    futures:(function(){ try{ return { chart:FUTMODE.chart, underlying:FUTMODE.underlying, r:FUTMODE.r,
                                       live:!!FUTMODE.live, approx:!!FUTMODE.approx, ok:!!FUTMODE.ok }; }catch(eFu){ return null; } })(),
    event:(function(){ try{ return eventTagLabel(); }catch(eEv){ return null; } })(),
    // (v10.51) FCHIST — raw Flr/Ceil strike samples. Carried in the export so the
    // day-over-day rolling study is computable once 2+ sessions exist. NOT a verdict:
    // no rolling value is computed anywhere in the panel yet.
    flrCeilHist:(function(){ try{ var o={}; RECORDER_SYMS.forEach(function(s){ o[s]=fcHistOf(s); }); return o; }catch(eFC){ return null; } })(),
    features:(function(){ try{ registerCoreFeatures(); return FEATURES.map(function(f){ return {key:f.key,label:f.label,phase:f.phase,fwd:f.fwd,rule:(f.rule&&f.rule.id)||null}; }); }catch(eFx){ return []; } })(),
    rules:(function(){ try{ return rulesLoad(); }catch(eRl){ return null; } })(),
    questions:(function(){ try{ return seedQuestions(); }catch(eQ){ return []; } })()
  };
}
var SAVED_TODAY=null;   // (v10.17) date-key of the day exported this session; drives the Analysis-tab banner
function saveDayToFile(dateKey){
  // (v11.0 audit G1/G11) ONE export path. The manual button used to download `gex_<date>.json`
  // (a name the push task never looks for) while the auto export wrote `data/<date>.json`; the
  // banner flipped only for the download. Both buttons now go through repoExportDay (repo folder
  // first, download of the SAME filename as fallback) and success flips the banner.
  // ⚠ (v14.51) BOTH PATHS MUST HONOUR THE REFUSAL. repoExportDay was handed `dateKey||TODAY`, which
  // reintroduced the wall-clock day the guard exists to avoid; and a refused payload must never be
  // written or downloaded. Build FIRST, check, then choose a path.
  var payload=null;
  try{ payload=buildDayExport(dateKey); }catch(eB){ console.warn('[GPTS] export build failed',eB); return null; }
  if(!payload || payload.empty){
    console.warn('[GPTS] '+((payload&&payload.refused)||'export refused — no recorded bars for that day'));
    return null;
  }
  try{ if(typeof repoExportDay==='function'){ repoExportDay(payload.date, false); return payload.date+'.json'; } }catch(e0){}
  try{
    var name=payload.date+'.json';
    var blob=new Blob([JSON.stringify(payload)],{type:'application/json'});
    var url=URL.createObjectURL(blob);
    var a=document.createElement('a');
    a.href=url; a.download=name; document.body.appendChild(a); a.click();
    setTimeout(function(){ document.body.removeChild(a); URL.revokeObjectURL(url); },1500);
    SAVED_TODAY=payload.date;
    if(typeof render==='function') render();   // refresh banner to "saved" state
    return name;
  }catch(e){ console.warn('[GPTS] saveDayToFile failed',e); return null; }
}
window.__gptsDebug.buildDayExport = buildDayExport;
window.__gptsDebug.saveDayToFile = saveDayToFile;
window.__gptsDebug.LASTFEED = LASTFEED;
