function legClone(s){ try{ return JSON.parse(JSON.stringify(s)); }catch(e){ return legBlank(s&&s.dir); } }
// ---------------------------------------------------------------------------
// PURE state machine. ctx = { dirIn:'dn'|'up'|'none', px, close, levels[], kingK, t, bar }
