window.__gptsDebug.features=function(){ registerCoreFeatures(); return FEATURES.map(function(f){ return {key:f.key,label:f.label,phase:f.phase,fwd:f.fwd,questions:(f.questions||[]).length,rule:f.rule&&f.rule.id}; }); };
