function cpRows(sym){
  try{
    var f=LASTFEED[sym||'SPY']; if(!f||!f.j) return null;
    var snaps=f.j.levels||[];
    var PK=pickSnapshot(snaps); if(!PK) return null;
    var last=PK.snap; var l=(last&&last.l)||[];
    if(!l.length) return null;
    var lt=0, eq=0, gt=0, noNet=0, rows=[];
    for(var i=0;i<l.length;i++){
      var n=l[i];
      if(typeof n.k!=='number' || typeof n.v!=='number'){ continue; }
      if(typeof n.net!=='number'){ noNet++; continue; }
      var v=Math.abs(n.v), nt=n.net, an=Math.abs(nt), tol=Math.max(1e-6, v*1e-9);
      if(an < v-tol) lt++; else if(an <= v+tol) eq++; else gt++;
      // (v11.17 SIGN FIX) put=(v+net)/2, NOT call=(v+net)/2. Verified against their published SPY page:
      // with the old assignment our put wall came out 756 and the book read call-heavy (ratio 1.44);
      // with this one the put wall is 760 — exactly their number in BOTH their 0DTE and next-week views —
      // and the book reads put-heavy (0.70) like theirs (0.02 / 0.36). Skylit's `net` is positive on a
      // put-dominated strike, which is the opposite of the call-positive convention I had assumed.
      rows.push({ k:n.k, v:v, net:nt, call:(v-nt)/2, put:(v+nt)/2 });
    }
    if(!rows.length) return null;
    rows.sort(function(a,b){ return a.k-b.k; });
    // gt>0 would mean v is not a total. Refuse rather than emit a decomposition we cannot justify.
    return { rows:rows, lt:lt, eq:eq, gt:gt, noNet:noNet, ok:(gt===0 && lt>0),
             snapIdx:PK.idx, snapBack:PK.steppedBack, degenerate:PK.degenerate,
             exps:(f.j.expirations||null), step:(f.j.strike_interval!=null?f.j.strike_interval:null),
             t:(last&&last.t)||null };
  }catch(e){ return null; }
}
// The walls THEIR way: call wall on CALL gamma, put wall on PUT gamma. Not a net proxy.
function cpLevels(sym){
  sym=sym||'SPY';
  try{
    var D=cpRows(sym); if(!D) return null;
    if(!D.ok && D.gt>0) return { err:'|net| exceeds v on '+D.gt+' strikes — v is not a total here, so calls and puts cannot be separated', lt:D.lt, eq:D.eq, gt:D.gt };
    var px=(STATE[sym]||{}).price; if(typeof px!=='number') return { err:'no price yet' };
    // (v11.20) DELEGATE. This function used to carry its OWN copy of the wall/crossing logic, so when
    // v11.18 fixed zero gamma to take the crossing NEAREST SPOT, this path kept the old first-crossing
    // behaviour and went on returning 479.7 against a spot of 762.57. Two implementations of one rule is
    // how a fix half-lands. There is now one: cpFromPayload.
    var f=LASTFEED[sym];
    var L=cpFromPayload(f&&f.j, px); if(!L) return null;
    return { px:px, callWall:L.cr, callWallGex:L.crGex, putWall:L.ps, putWallGex:L.psGex,
             zg:L.hvl, mag:L.mag, totalCall:L.totalCall, totalPut:L.totalPut, ratio:L.ratio,
             crSuppressed:L.crSuppressed, psSuppressed:L.psSuppressed,
             callShare:L.callShare, putShare:L.putShare, nCross:L.nCross,
             n:L.n, kMin:L.kMin, kMax:L.kMax, step:D.step, exps:D.exps, lt:D.lt, eq:D.eq, subset:true };
  }catch(e){ return null; }
}
