// ============ (v11.17) ONE BLOCK. ONE SCALE. NO DUPLICATES. ============
// The v11.16 card printed the same levels three times — a %King block, a call/put block and a broken
// SPX block — with "SPY 765" hung off every row while the chart was on ES. The user's instruction was
// exact: one set of levels, on the instrument the chart is showing, consistent with a third-party page.
//
// SOURCE PRECEDENCE, best first. Each level takes the best source that can actually produce it:
//   1. self-fetched full-chain set  (call/put decomposed, every expiration)  -> CR, PS, FLIP, Mag
//   2. self-fetched 0DTE set        (call/put decomposed, today only)        -> CR0, PS0
//   3. the passive feed             (call/put decomposed, top-60 x 4 exps)   -> fallback for all of them
//   4. %King ladder                 (no decomposition)                       -> last resort, tagged
// A row is only shown ONCE. A 0DTE row appears only when its strike genuinely differs from the
// structural one, because a 0DTE row that repeats CR tells the reader nothing.
function lvlUnified(sym){
  sym=sym||'SPY';
  try{
    var px=(STATE[sym]||{}).price; if(typeof px!=='number') return null;
    var full=expSetLevels(sym,'week'), dte0=expSetLevels(sym,'dte0');
    var passive=null; try{ passive=cpLevels(sym); }catch(e0){}
    if(passive && passive.err) passive=null;
    var out={ px:px, rows:[], src:null, note:null, ratio:null, nExps:null, n:null, ageMin:null };
    // (v11.20) THE 0DTE SET CAN CARRY THE CARD ON ITS OWN. Right after a reload the full-chain set is
    // still in flight and the passive feed has not arrived, but the 0DTE set often has — and the card
    // rendered BLANK because dte0 was only ever treated as an extra row, never as a source. Precedence is
    // full chain, then 0DTE, then the passive feed; whichever answers is named on the face so a today-only
    // read is never mistaken for a structural one.
    var P=null, dte0IsPrimary=false;
    if(full){ P=full; out.src='week'; out.nExps=full.nExps; out.n=full.n; out.ratio=full.ratio; out.ageMin=full.ageMin; }
    else if(dte0){ P=dte0; dte0IsPrimary=true; out.src='0dte'; out.nExps=dte0.nExps; out.n=dte0.n; out.ratio=dte0.ratio; out.ageMin=dte0.ageMin; }
    else if(passive){ out.src='feed'; out.n=passive.n; out.ratio=passive.ratio;
      P={ cr:passive.callWall, crGex:passive.callWallGex, ps:passive.putWall, psGex:passive.putWallGex,
          hvl:passive.zg, mag:passive.mag, kMin:passive.kMin, kMax:passive.kMax,
          crSuppressed:passive.crSuppressed, psSuppressed:passive.psSuppressed,
          callShare:passive.callShare, putShare:passive.putShare, hvlFar:passive.hvlFar }; }
    if(!P) return null;
    // Mag: the heaviest strike overall. The passive path does not compute it, so fall back to the King.
    var mag=P.mag; if(mag==null){ try{ var kg=(STATE[sym]||{}).king; if(typeof kg==='number') mag=kg; }catch(e1){} }
    // (v11.17.1) When two levels land on the SAME strike the row MERGES its labels — it does not silently
    // drop one. The live card showed "CR / Mag / FLIP" with no PS at all, because the put wall and the
    // magnet were both 760 and PS was added last. "PS·Mag 760" is the true reading and it is more
    // informative than either label alone: the heaviest strike in the book is also the floor.
    function add(id, k, gex, tag){
      if(k==null) return;
      for(var i=0;i<out.rows.length;i++){
        if(Math.abs(out.rows[i].k-k)<0.005){
          if(out.rows[i].id.indexOf(id)<0){
            // (v11.22) THE WALL LEADS. "Mag·PS" read as "PS is missing" on the live card — the label a
            // trader is looking for was second and easy to miss. Walls are the trade-location levels;
            // the magnet is the destination. Order them that way.
            var ids=out.rows[i].id.split('·'); ids.push(id);
            var rank={CR:0, CR0:1, PS:0, PS0:1, FLIP:2, Mag:3};
            ids.sort(function(a,b){ return (rank[a]==null?9:rank[a])-(rank[b]==null?9:rank[b]); });
            out.rows[i].id=ids.join('·');
          }
          if(out.rows[i].gex==null && gex!=null) out.rows[i].gex=gex;
          return;
        }
      }
      out.rows.push({ id:id, k:k, gex:(gex==null?null:gex), tag:tag||null,
                      dist:+(k-px).toFixed(2), distPct:+(((k-px)/px)*100).toFixed(2) });
    }
    out.crSuppressed=P.crSuppressed||null; out.psSuppressed=P.psSuppressed||null;
    out.callShare=(P.callShare==null?null:P.callShare); out.putShare=(P.putShare==null?null:P.putShare);
    add('CR',  P.cr,  P.crGex);
    add('FLIP', P.hvl, null);
    add('Mag', mag,   null);
    add('PS',  P.ps,  P.psGex);
    // 0DTE rows: only when they say something the structural rows did not — and never when the 0DTE set
    // IS the structural read, or every row would be added to itself.
    if(dte0 && !dte0IsPrimary){
      add('CR0', dte0.cr, dte0.crGex, '0DTE');
      add('PS0', dte0.ps, dte0.psGex, '0DTE');
      out.dte0Exps=dte0.nExps; out.dte0N=dte0.n;
    }
    out.rows.sort(function(a,b){ return b.k-a.k; });
    // (v11.22) NOTHING GOES MISSING SILENTLY. The user asked to see CR0/CR/PS/PS0/FLIP/Mag; when one has no
    // value the card must SAY so with the reason, not just leave a gap. An absent level is a finding — a
    // 0DTE book with no call-dominant strike above spot is exactly what a third-party page shows as N/A.
    var shown={};
    out.rows.forEach(function(r){ r.id.split('·').forEach(function(id){ shown[id]=1; }); });
    out.absent=[];
    function miss(id, why){ if(!shown[id]) out.absent.push({ id:id, why:why }); }
    miss('CR',  P.crSuppressed?'no call-dominant strike above spot':'not read');
    miss('PS',  P.psSuppressed?'no put-dominant strike below spot':'not read');
    miss('CR0', dte0?(dte0.crSuppressed?'none today — 0DTE book is all put':'same as CR'):'0DTE set not loaded');
    miss('PS0', dte0?(dte0.psSuppressed?'none today — 0DTE book is all call':'same as PS'):'0DTE set not loaded');
    miss('Mag', 'no dominant strike');
    out.hvlMissing = (P.hvl==null);
    out.hvlFar = P.hvlFar||null;
    out.degenerate = !!P.degenerate; out.snapBack = (P.snapBack==null?null:P.snapBack);
    out.snapMixed = (P.snapMixed==null?null:P.snapMixed);
    out.regime = (P.hvl!=null) ? ((px>=P.hvl)?'posGamma':'negGamma') : null;
    out.kMin=P.kMin; out.kMax=P.kMax;
    return out;
  }catch(e){ return null; }
}
// The card. Values are shown in the CHART's instrument only — no second scale, no "SPY 765" tail.
// ============ (v11.21) WHERE PRICE IS GOING — the gamma structure as a directional read ============
// The user's brief: "today price was going down to strong gamma levels. I need to know this so I am
// prepared for trading to know where price is going." Levels on their own are trivia; what matters is the
// PATH they imply and the two places a reversal is most likely.
//
// The frame, in the vocabulary the rest of the panel already uses:
//   Mag (peak |gamma|) is the DESTINATION — the strike dealers hedge around hardest, so price is drawn to it.
//   PS is the FLOOR and CR the CEILING — the two edges of the cage, where a deflection is most likely.
//   Position inside that cage says how much room is left before the next reversal zone.
// DESCRIPTIVE ONLY. It says where the structure points, never what to do about it, and it carries no
// weight in the direction vote until the scorecard has earned it (eff n >= 20, three walk-forward sessions).
var WALL_HIST={};              // per symbol: the last CR/PS/Mag and when each was first seen there
var GEXPATH_PIN_ATR=0.35;      // within this fraction of ATR of the magnet counts as pinned, not travelling
function gexPath(sym){
  sym=sym||'SPY';
  try{
    var U=lvlUnified(sym); if(!U) return null;
    var px=U.px; if(typeof px!=='number') return null;
    var byId={}; (U.rows||[]).forEach(function(r){
      r.id.split('·').forEach(function(id){ if(!byId[id]) byId[id]=r.k; }); });
    var mag=byId['Mag'], cr=(byId['CR']!=null?byId['CR']:byId['CR0']), ps=(byId['PS']!=null?byId['PS']:byId['PS0']);
    var a=0.35; try{ var av=atr(sym); if(typeof av==='number' && av>0) a=av; }catch(e0){}
    var out={ px:px, mag:(mag==null?null:mag), cr:(cr==null?null:cr), ps:(ps==null?null:ps), atr:+a.toFixed(2) };
    // the cage and where price sits inside it
    if(cr!=null && ps!=null && cr>ps){
      out.cage={ lo:ps, hi:cr, span:+(cr-ps).toFixed(2),
                 pos:Math.max(0, Math.min(100, Math.round(((px-ps)/(cr-ps))*100))) };
      out.toCeil=+(cr-px).toFixed(2); out.toFloor=+(px-ps).toFixed(2);
    }
    if(mag==null){ out.state='no-magnet'; out.line='no dominant gamma strike'; return out; }
    var d=+(mag-px).toFixed(2);
    out.magDist=d; out.magAtr=+(Math.abs(d)/(a||1)).toFixed(2);
    if(Math.abs(d) <= a*GEXPATH_PIN_ATR){
      out.state='pinned'; out.dir=0;
      out.line='pinned at '+fmtLvl(mag);
    } else {
      out.state='toward'; out.dir=(d>0?1:-1);
      out.line=(d>0?'↑ toward ':'↓ toward ')+fmtLvl(mag);
    }
    // is price actually travelling that way, or is the magnet behind it?
    try{
      var cs=(closedCandles(sym)||[]).slice(-6);
      if(cs.length>=3 && cs[0].c!=null){
        var mv=px-cs[0].c;
        out.mv=+mv.toFixed(2);
        out.agree=(out.dir===0)?null:((mv>0?1:(mv<0?-1:0))===out.dir);
      }
    }catch(e1){}
    // which edge is the live reversal zone: the one price is heading at
    if(out.dir>0 && cr!=null){ out.reversalAt='CR'; out.reversalK=cr; out.reversalDist=+(cr-px).toFixed(2); }
    else if(out.dir<0 && ps!=null){ out.reversalAt='PS'; out.reversalK=ps; out.reversalDist=+(px-ps).toFixed(2); }
    else if(out.cage){ out.reversalAt=(out.cage.pos>=50?'CR':'PS'); out.reversalK=(out.cage.pos>=50?cr:ps); }
    // does the magnet sit BEYOND the near edge? then the edge is the thing that gets tested first
    if(out.dir<0 && ps!=null && mag<ps){ out.through='PS'; }
    if(out.dir>0 && cr!=null && mag>cr){ out.through='CR'; }
    return out;
  }catch(e){ return null; }
}
// One line for the face. Short, and it never tells anyone what to do.
// ---- (v11.21) SANITY CHECK ------------------------------------------------------------------------
// The user asked for a periodic automated check against a third-party page. That is NOT possible from
// inside the panel and the reason is settled, not a guess: their server sends no CORS header, verified in
// the live console — `fetch(...)` returns "BLOCKED Failed to fetch" — and the @grant that would bypass it
// sandboxes this script, which would kill the window.fetch hook the whole tape depends on.
//
// So the check is INTERNAL: assertions that would catch a wrong level without needing anyone else's data.
// Every one of these fired at least once during development, which is why they are here rather than in a
// comment. `__gptsDebug.sanity()` runs them on demand and `sanityBadge()` surfaces a failing count.
//
// The one comparison that DOES need their numbers is manual: paste them via the IF button and
// __gptsDebug.sanity() reports the deltas. Note our week window ("through this Friday") is NOT their "Next
// week" (a rolling 7 days), so a CR difference mid-week is a definition difference and is NOT flagged.
function gexSanity(sym){
  sym=sym||'SPY';
  var out={ sym:sym, checks:[], failed:0 };
  function chk(id, pass, detail){ out.checks.push({ id:id, pass:!!pass, detail:(detail==null?null:detail) }); if(!pass) out.failed++; }
  try{
    var U=null; try{ U=lvlUnified(sym); }catch(e){}
    if(!U){ chk('haveLevels', false, 'no level set at all'); return out; }
    chk('haveLevels', true);
    var px=U.px, byId={};
    (U.rows||[]).forEach(function(r){ r.id.split('·').forEach(function(id){ if(byId[id]==null) byId[id]=r.k; }); });
    var cr=byId['CR'], ps=byId['PS'], mag=byId['Mag'];
    // 1. the walls must straddle spot. If they do not, the sign convention has flipped — the single
    //    most dangerous failure here, because both numbers still look like plausible levels.
    chk('crAboveSpot', cr==null || cr>px, cr!=null?('CR '+cr+' vs px '+px.toFixed(2)):'no CR');
    chk('psBelowSpot', ps==null || ps<px, ps!=null?('PS '+ps+' vs px '+px.toFixed(2)):'no PS');
    // 2. every displayed level must lie inside the strike range we actually read
    var inRange=true, bad=null;
    (U.rows||[]).forEach(function(r){ if(U.kMin!=null && U.kMax!=null && (r.k<U.kMin || r.k>U.kMax)){ inRange=false; bad=r.id+':'+r.k; } });
    chk('levelsInRange', inRange, bad);
    // 3. no two rows may share a strike — that was the duplicate-row bug
    var ks=(U.rows||[]).map(function(r){ return r.k; });
    chk('noDuplicateStrikes', ks.length===ks.filter(function(v,i){ return ks.indexOf(v)===i; }).length, ks.join(','));
    // 4. the levels must be near price. A wall 20% away is a tail artefact, not a level.
    var far=null;
    (U.rows||[]).forEach(function(r){ if(px>0 && Math.abs(r.k-px)/px > 0.10) far=r.id+':'+r.k; });
    chk('levelsNearPrice', far===null, far);
    // 5. the set must be fresh; a stale set silently showing yesterday's walls is worse than none
    chk('setFresh', U.ageMin==null || U.ageMin<20, U.ageMin!=null?(U.ageMin+'m old'):'no age');
    // (v11.24) THE ONE THAT MATTERS MOST OUTSIDE RTH. The newest frame of the feed is the still-forming
    // bar; after the close it degenerates to net=+/-v on every strike, so a call/put split read from it is
    // fabricated. Levels built on that frame must never be presented as if they were measured.
    chk('snapshotHasDecomposition', !U.degenerate, U.degenerate?('newest frames carry no call/put split'+(U.snapBack?(' — stepped back '+U.snapBack):'')):'ok');
    // 6. magnet must be a real strike we hold
    chk('magnetPresent', mag!=null, mag);
    // 7. THEIR numbers, if entered by hand — reported, and only flagged where the windows agree
    try{
      var IF=ifManLevels();
      if(IF && !IF.err){
        out.theirs={ cr:IF.cw, ps:IF.pw, hvl:IF.zg, mag:IF.mag, ageMin:IF.ageMin, scale:IF.scale };
        if(IF.pw!=null && ps!=null) out.psDelta=+(ps-IF.pw).toFixed(2);
        if(IF.cw!=null && cr!=null) out.crDelta=+(cr-IF.cw).toFixed(2);
        // the PUT wall is the one that should agree: it held at the same strike across every one of their
        // expiry filters, so a window difference does not explain a gap here.
        if(out.psDelta!=null) chk('putWallMatchesTheirs', Math.abs(out.psDelta)<=1.01, 'delta '+out.psDelta);
        out.note='CR is NOT expected to match theirs: our window is "through this Friday", theirs is a rolling 7 days.';
      }
    }catch(eIF){}
  }catch(e){ chk('threw', false, String(e)); }
  return out;
}
window.__gptsDebug=window.__gptsDebug||{};
window.__gptsDebug.sanity=function(s){ return gexSanity(s||'SPY'); };

window.__gptsDebug=window.__gptsDebug||{};
window.__gptsDebug.path=function(s){ return gexPath(s||'SPY'); };

window.__gptsDebug=window.__gptsDebug||{};
window.__gptsDebug.unified=function(s){ return lvlUnified(s||'SPY'); };



// (v11.3.1, user-directed) PULLBACK CONTEXT — recorded on every pbEntry record so the hit rate can be sliced by the
// STRENGTH/WEAKNESS OF THE PULLBACK and the QUALITY OF THE NODE. The user's frame: how deep is the pullback, how far
// from the 50-SMA, is the node above/below the 50-SMA, does the pullback have speed/momentum, and is the node rolled /
// accumulating / decreasing / FRESH (a new node = dealers stepping in to stop the pullback). Non-voting, no face
// change; forward-only fields — they cannot be back-filled, which is why they ship now.
function _pbCtx(sym, pe){
  var out={ pb:null, sma:null, nodeCtx:null, stack:null };
  try{
    var cs=closedCandles(sym)||[]; var n=cs.length; if(!n||!pe||pe.level==null) return out;
    var px=(STATE[sym]||{}).price; if(px==null) return out;
    var a=0.5; try{ a=atr(sym)||0.5; }catch(eA){}
    // ---- the 50-SMA frame: where price is, where the LEVEL is, which side the node sits on
    var m=Math.min(50,n), sum=0; for(var i=n-m;i<n;i++){ sum+=cs[i].c; }
    var sma=sum/m; var dPx=px-sma, dLv=pe.level-sma;
    out.sma={ sma:+sma.toFixed(2), d:+dPx.toFixed(2), dAtr:+(dPx/Math.max(a,0.01)).toFixed(1),
              levelD:+dLv.toFixed(2), levelDAtr:+(dLv/Math.max(a,0.01)).toFixed(1),
              nodeSide:(Math.abs(dLv)<=0.2*a)?'at':(dLv>0?'above':'below'), win:m };
    // ---- pullback geometry, oriented by the DEFLECTION direction (dir<0 = dn leg, pullback UP into the level)
    var W=cs.slice(Math.max(0,n-30)); var dn=(pe.dir<0);
    var lo=Infinity, hi=-Infinity, loI=-1, hiI=-1;
    for(var j=0;j<W.length;j++){ if(W[j].l!=null&&W[j].l<lo){lo=W[j].l; loI=j;} if(W[j].h!=null&&W[j].h>hi){hi=W[j].h; hiI=j;} }
    var swing=hi-lo;
    if(isFinite(swing) && swing>0.01){
      var anchorI=dn?loI:hiI;                       // the leg extreme the pullback started from
      var retrace=dn?(px-lo):(hi-px);               // how far price has pulled back against the leg
      var bars=(W.length-1)-anchorI;                // pullback duration so far
      var withBars=0, tot=0, lastBody=null, prevBody=null;
      for(var q=anchorI+1;q<W.length;q++){ var B=W[q]; if(B.c==null||B.o==null) continue; tot++;
        var upC=B.c>B.o; if(dn?upC:!upC) withBars++;
        prevBody=lastBody; lastBody=Math.abs(B.c-B.o); }
      out.pb={ depth:+(Math.max(0,Math.min(1.5,retrace/swing))).toFixed(2),   // 0.3 shallow · 0.8 deep · >1 = past the leg origin
               swing:+swing.toFixed(2), retrace:+retrace.toFixed(2), bars:bars,
               paceAtr:(bars>0)?+((retrace/bars)/Math.max(a,0.01)).toFixed(2):null,   // pts/bar in ATR units: fast drive vs slow grind
               counterShare:tot?+(withBars/tot).toFixed(2):null,                      // share of bars closing WITH the pullback
               fading:(lastBody!=null&&prevBody!=null)?(lastBody<prevBody):null };    // the bar into the level shrank
    }
    // ---- the node's own life: fresh / rolled / building or bleeding (dealers' intent, in the user's words)
    var nc={ age:null, fresh:null, m15:null, fromPeak:null, rolledFrom:null, step:null };
    try{ var Ln=ledgerNode(sym, pe.level);
      if(Ln){ var ft=Ln.firstT||Ln.first||null;
        if(ft!=null){ var ageMin=Math.round((Date.now()/1000-ft)/60); if(isFinite(ageMin)&&ageMin>=0){ nc.age=ageMin; nc.fresh=(ageMin<=45); } }
        if(Ln.m15!=null) nc.m15=Ln.m15; if(Ln.fromPeak!=null) nc.fromPeak=Ln.fromPeak; } }catch(eL){}
    try{ var lg=legEngine(sym); if(lg&&lg.pbDetected&&Math.abs(lg.pbDetected.k-pe.level)<0.001){ nc.rolledFrom=lg.pbDetected.rolledFrom||null; nc.step=lg.pbDetected.step||null; } }catch(eG){}
    out.nodeCtx=nc;
    // ---- (v11.3.1, user) STACKED PULLBACK NODES: "many times there are 2-3 pullback nodes stacked close to each
    // other — judge which one is stronger, or the one with more retracement." Every meaningful node on the pullback
    // side within STACK_SPAN of the picked level is recorded {k, pct, state, m15, depth (its own retracement of the
    // leg)}, strongest first; `strongest` and `deepest` are named, `chosenRank` says where the picked level sits.
    try{
      var STACK_SPAN=1.5; var dnS=(pe.dir<0);
      var fl=null; try{ fl=nodeFlow(sym); }catch(eF){}
      var pool=((fl&&fl.nodes)||[]).filter(function(nn){ return nn.pct!=null && nn.pct>=PB_MIN_PCT
        && (dnS?(nn.k>px):(nn.k<px)) && Math.abs(nn.k-pe.level)<=STACK_SPAN && nn.state!=='gone'; });
      if(pool.length>=2 && out.pb && out.pb.swing>0.01){
        var lo2=dnS?(px-out.pb.retrace):null;
        var members=pool.map(function(nn){
          var ret=dnS?(nn.k-(px-out.pb.retrace)):((px+out.pb.retrace)-nn.k);   // retracement of the leg AT that node
          return { k:nn.k, pct:nn.pct, state:nn.state, m15:(nn.m15!=null?nn.m15:null),
                   depth:+(Math.max(0,Math.min(1.5,ret/out.pb.swing))).toFixed(2) };
        }).sort(function(a,b){ return b.pct-a.pct; });
        var deepest=members.slice().sort(function(a,b){ return b.depth-a.depth; })[0];
        var rank=1+members.findIndex(function(mm){ return Math.abs(mm.k-pe.level)<0.001; });
        out.stack={ n:members.length, members:members.slice(0,3), strongest:members[0].k, deepest:deepest.k,
                    chosenRank:(rank>0?rank:null), span:+(Math.max.apply(null,members.map(function(mm){return mm.k;}))-Math.min.apply(null,members.map(function(mm){return mm.k;}))).toFixed(2) };
      }
    }catch(eSk){}
  }catch(e){}
  return out;
}
window.__gptsDebug.pbEntry=function(s){ try{ return pbEntryPick(s||'SPY'); }catch(e){ return String(e); } };

var LAST_READ={};   // (v11.0 G8) the last READ per sym — now written by readState(), not by a render
var READ_SYM='SPY';  // (v11.0.1) the sym read3Beat is speaking for (it has no sym parameter)
// (v15.53, D4) THE READ IS COMPUTED, NOT RENDERED-THEN-REMEMBERED. Until this build LAST_READ was
// written only inside readBlock44 — which lives in the `else` of render() that CFG.panelV3 never lets
// run. So every `dir` record since v11.0 carried read:null, READ_SYM was never set, and the G8 fix
// ("the sentence the user saw is on the record") was inert from the day it shipped. The `dir`
// feature now calls this directly on the closed bar; the face is free to draw it or not.
function readState(sym){
  sym=sym||'SPY';
  var S=STATE[sym]||{}; var px=S.price; if(px==null) return null;
  var m=nodeMapModel(sym); if(!m||!m.ok) return null;
  var sp=null; try{ sp=spineOf(sym); }catch(eSp){}
  var d=(sp&&sp.dir)||(function(){ try{ return directionGrade(sym); }catch(e){ return {dir:'SIDE',grade:'C',disp:'C',inputs:{}}; } })();
  var L=(sp&&sp.inPlay); if(L==null){ try{ L=inPlayZone(sym); }catch(eL){ L=null; } }
  var dr; try{ dr=driftRead(sym); }catch(eDr){ dr={dir:0,verdict:'NONE'}; }
  var dirWord=d.dir||'SIDE';
  var dirNum=dirWord==='UP'?1:(dirWord==='DN'?-1:0);
  var tgtK=null, tgtRole='';
  try{
    if(L){ var fr=tradeFrame(sym,L,dirNum||nodeHoldDir(L,px));
      if(fr && fr.tgt!=null){ tgtK=fr.tgt;
        var tl=(m.levels||[]).filter(function(x){return Math.abs(x.k-tgtK)<0.001;})[0]; if(tl) tgtRole=zoneRole(tl); } }
  }catch(eFr){}
  var legR=(sp&&sp.leg)||null;
  if(!legR){ try{ legR=legEngine(sym); }catch(eLg){ legR=null; } }
  READ_SYM=sym;
  var v=read3Beat(dirWord, L, px, m.flr, m.ceil, dr, tgtK, tgtRole, d.relation||null, legR, d.capped||null);
  var out={ t:Date.now(), verdict:v.verdict, sentence:String(v.sentence||'').slice(0,240), voiceId:v.voiceId||null,
            legDir:legR?legR.dir:'none', legPhase:legR?legR.phase:'none', dirSrc:legR?(legR.dirSrc||'sma'):null,
            map:String(v.structure||'').slice(0,240), structureId:v.structureId||null,
            _v:v, _d:d, _L:L, _m:m, _legR:legR, _dr:dr, _px:px, _tgtK:tgtK, _tgtRole:tgtRole };
  LAST_READ[sym]=out;
  return out;
}
window.__gptsStudyRun=function(){ studyRun(function(r){ try{ render(); }catch(e){} }); };
window.__gptsRepoExport=function(d){ repoClickExport(d||TODAY); };   // (v15.71) the click asks Chrome inside the gesture, then writes today and any earlier day
window.__gptsRepoPick=function(){ repoPickFolder(); };
window.__gptsRepoCoverage=function(){ repoCoverage(function(c){ console.log('[GEX repo]',c); }); };


// #7 STALE-FEED GUARD. Freshness state from the age of the last feed update,
// with thresholds ADAPTIVE to the observed cadence (amber ~2x, red ~4x), so it
// self-tunes instead of guessing fixed seconds. Falls back to POLL_MS-based
// thresholds until we have observed a cadence.
var FEED_AGES = { SPY:[], QQQ:[] };
var FEED_LAST_TS = { SPY:0, QQQ:0 };
function observeFeedCadence(sym, ts){
  var prev=FEED_LAST_TS[sym];
  if(prev){ var gap=ts-prev; if(gap>0 && gap<600000){ FEED_AGES[sym].push(gap); if(FEED_AGES[sym].length>10) FEED_AGES[sym].shift(); } }
  FEED_LAST_TS[sym]=ts;
}
function feedCadenceMs(sym){
  var a=FEED_AGES[sym];
  if(!a || !a.length) return POLL_MS;
  var s=0; for(var i=0;i<a.length;i++) s+=a[i];
  return s/a.length;
}
// Returns { state:'live'|'amber'|'red'|'idle', age, col, label }.
function feedFreshness(sym){
  var f=LASTFEED[sym];
  if(!f) return { state:'idle', age:null, col:PAL.sub, label:'idle' };
  var age=Date.now()-f.ts;
  var cad=feedCadenceMs(sym);
  var amber=cad*2, red=cad*4;
  var state, col;
  if(age>=red){ state='red'; col=PAL.shortAccent; }
  else if(age>=amber){ state='amber'; col=PAL.amber; }
  else { state='live'; col=PAL.longAccent; }
  var secs=Math.round(age/1000);
  return { state:state, age:age, col:col, label:(secs<60?(secs+'s'):(Math.round(secs/60)+'m')) };
}
function feedStatusHtml(){
  var now=Date.now();
  var f=LASTFEED.SPY;
  var txt, col;
  var age=f?(now-f.ts):Infinity;
  var feedLive = f && age<=FEED_STALE_MS;
  if(feedLive){
    // (v10.48) When the display is VEX or GEX+VEX, structure still comes from the
    // pure-gamma feed — say so explicitly rather than implying the displayed mode.
    if(LASTDISP.SPY && LASTDISP.SPY!=='gamma'){
      var dm=(LASTDISP.SPY==='vanna')?'VEX':'GEX+VEX';
      txt='SPY:gamma·feed (disp '+dm+')';
    } else { txt='SPY:'+f.feed; }
    col=PAL.longAccent;
  }
  else {
    // No live network feed — are we running off the visible DOM tape instead?
    var tp=tapeMap('SPY');
    var tapeLive = tp && tp.pct && tp.count>=3;
    if(tapeLive){ txt='SPY:tape'; col=PAL.blue; }        // fallback active, panel populated
    else if(f){ txt='SPY:stale'; col=PAL.amber; }
    else { txt='SPY:idle'; col=PAL.sub; }
  }
  // (v10.49 A) VEX honesty: if the vanna book is stale AND we have no captured
  // Authorization header, the self-fetch cannot succeed — say "waiting", never imply live.
  var vexTxt='';
  try{
    var vx=LASTVEX.SPY;
    var vexStale = !vx || (now-vx.ts)>FEED_STALE_MS;
    if(vexStale && !LASTAUTH){
      vexTxt='<span title="VEX (vanna) is stale and no Authorization header has been captured from a real gex/levels request yet, so the out-of-band self-fetch cannot authenticate. It will resolve as soon as the Skylit app makes its next request. Drift falls back to NONE until then." style="color:'+PAL.sub+';opacity:.7">vex ⏳</span>';
    } else if(vexStale){
      vexTxt='<span title="VEX (vanna) is stale; a self-fetch is in flight." style="color:'+PAL.sub+';opacity:.7">vex ⏳</span>';
    }
  }catch(eVx){}
  // (v10.38) TAPE-PARSE HEALTH — visible, not silent.
  // kingResolve() sets kingConflict/parseSuspect when the tape parse violates a
  // King invariant. Before v10.38 those flags were WRITTEN AND NEVER READ, which
  // is exactly how the 2026-08-14 King desync ran live and unnoticed: the flag
  // was true the whole time. A parse failure now shows on the panel.
  var warn='';
  try{
    var tpH=tapeMap('SPY');
    if(tpH && tpH.kingConflict){
      var why = tpH.parseSuspect==='king-not-100'
        ? 'King '+(tpH.kingTagged!=null?tpH.kingTagged:'?')+' read '+(tpH.taggedPct!=null?tpH.taggedPct:'?')+'% not 100%'
        : 'strike '+(tpH.kingRival!=null?tpH.kingRival:'?')+' rivals King';
      warn='<span title="Tape parse invariant failed: '+why+'. The $K-tagged King is still being used. '+
           'Structural reads may be degraded — re-check before trusting node strengths." '+
           'style="color:'+PAL.shortAccent+';font-weight:600">⚠ tape</span>';
    }
  }catch(eW){}
  // ⚠⚠ (v14.53) THE IRT PERMISSION WARNING BELONGS ON THE FACE, NOT IN THE GEAR.
  // Measured live 2026-08-27: the export had been dead for 54 minutes and the only evidence was a
  // stale error inside the config drawer, which nobody opens while trading. Chrome drops the
  // folder permission on every page load and requestPermission cannot run from a timer, so this
  // state happens EVERY MORNING and costs a whole session of levels if it is not visible.
  // It is deliberately the loudest thing in the footer and it names the fix in four words.
  try{
    if(typeof IRT_LAST==='object' && IRT_LAST && IRT_LAST.needsGesture){
      warn+=(warn?' ':'')+'<span title="'+
        'The IRT FlexLevels export is NOT running. Chrome resets the output folder permission to '+
        '\'prompt\' on every page load, and the browser refuses to re-request it from a background '+
        'timer because that needs a user gesture. One click restores it for the session: open the '+
        'gear and press the IRT Export-now button, or re-pick the folder. Exports then resume on '+
        'their own cadence. This is not a data problem and the levels are being built fine."'+
        ' style="color:'+PAL.shortAccent+';font-weight:700">⚠ IRT needs a click</span>';
    }
  }catch(eIW){}
  // ⚠⚠ (v14.55) A MODE YOU CANNOT SEE IS A MODE THAT LIES. The whole face is showing a book
  // that stopped moving hours ago, so it says so — in the FOOTER, where the eye already goes, not
  // in the gear drawer nobody opens. It names the SESSION and the CLOCK TIME the book froze at,
  // because "stale" without a timestamp is not a disclosure, it is a mood.
  // ⚠ It appends to `warn`, the variable THIS scope builds. The first draft appended to `out`
  // from inside the IRT branch — syntactically fine, silently dead, swallowed by the catch.
  // That is failure pattern #5, and node --check cannot see it.
  try{
    if(showingStaleBook()){
      var LB=null; try{ LB=lastBookLoad(lastBookGov(activeSym())); }catch(eLB){}
      LB=LB||{};
      // ⚠⚠⚠ (v15.35) THE FREEZE BADGE WAS PRINTING A 1970 TIMESTAMP. `LB.ts` is epoch MILLISECONDS
      // and `fmtClock(ts)` does `new Date(ts)` — also milliseconds. Dividing by 1000 first handed it
      // SECONDS, which `new Date` reads as milliseconds: 1788296340000 → 1788296340 → 1970-01-21,
      // which renders in Chicago as **10:44 am**. The operator saw "2026-09-01 book — frozen 10:44
      // am" on a book actually latched at 14:59, and 10:44 is plausible enough to be believed.
      // ⚠ THE ONE LABEL THAT SAYS WHICH BOOK YOU ARE LOOKING AT WAS THE ONE THAT LIED. A stale-book
      // badge exists to answer "how old is this" — a wrong answer there is worse than no badge,
      // because it converts a disclosure into a false reassurance.
      // ⚠ The comment two lines up says it "names the SESSION and the CLOCK TIME the book froze at".
      // It did name them. It just converted the units on the way, and nothing checked the output.
      var lbT=''; try{ lbT=fmtClock(LB.ts||0); }catch(eLT){}
      warn+=(warn?' ':'')+'<span title="THE MARKET IS CLOSED AND THE LIVE BOOK HAS ROLLED. Skylit drops the expired chain at the close, so the ladder on the page is the NEXT expiry with every rate of change at zero. What you are looking at is the last healthy reading of the '+
        (LB.day||'')+' session, frozen at '+lbT+' \u2014 real numbers, not live ones. Nothing is recorded while this shows: the recorder is blind to it by construction (recorderBlind), so it can never enter data/<day>.json as though it were live. Turn it off in the gear to watch the overnight book instead."'+
        ' style="color:#7cc7ff;font-weight:800">\u25cf '+(LB.day||'last session')+' book \u2014 frozen '+lbT+'</span>';
    }else{
      // ⚠⚠ (v15.03) THE EMPTY LADDER NOW EXPLAINS ITSELF. He was handed a blank ladder after the
      // close with nothing saying why, and read it as a broken build — "you have totally messed up
      // everything.. look at the ladder". The cause was specific and knowable: on a QQQ chart the
      // last-session latch has no QQQ book, because only SPXW was ever saved. **An absence the code
      // can explain must never be shown as a blank.**
      var _why=null; try{ _why=staleBookWhy(activeSym()); }catch(eW){}
      if(_why) warn+=(warn?' ':'')+'<span title="'+g3esc(_why)+'" style="color:#e3b341;font-weight:800">'+
                     '\u25cb no last-session book for '+g3esc(activeSym())+'</span>';
    }
  }catch(eLB){}
  // ⚠⚠ (v15.06) A PIN THAT DISAGREES WITH THE CHART MUST NEVER BE SILENT. The panel is pinned to
  // the SPX book by default, so a QQQ or ES tab now shows SPX numbers — which is what he asked for,
  // and is also exactly how someone reads a price off the wrong instrument. The face says which
  // book it is reading whenever that differs from the chart in front of him.
  try{
    var _pn=mktPinned();
    if(_pn) warn+=(warn?' ':'')+'<span title="The panel is PINNED to the '+g3esc(_pn.pin)+
      ' book while the chart shows '+g3esc(_pn.chart)+'. Every number here is the '+g3esc(_pn.pin)+
      ' book \u2014 that is deliberate: the 284-session HOD/LOD corpus, the GREEN/RED rule and the '+
      'deflection geometry all stand on it. Change it under Settings \u2192 Market, or choose Auto to '+
      'follow the chart." style="color:#7cc7ff;font-weight:800">\u25c9 '+g3esc(_pn.pin)+' book (chart: '+
      g3esc(_pn.chart)+')</span>';
  }catch(ePn){}
  // (v10.17) The 📥 Save Day button moved OFF the dashboard footer and INTO the
  // Analysis tab as an in-tab "Save & prep review" banner (the tab is the trigger).
  // (v10.52) PIPELINE INDICATOR — replaces the v10.50 feed/vex/rec dots. Those three
  // asked "is the tool alive?". They could all be green while the day's data never
  // left the browser, which is exactly what happened: v10.50 also dropped the old
  // "saved ✓ / not saved" text, so a download-only export looked identical to a real
  // repo write. The four stages below follow the data instead — recorded → saved →
  // pushed → review — and feed/vex liveness is folded into the `rec` hover so no
  // health signal was lost. The 💾 export / 📁 pick controls and the ⚠ tape-parse flag
  // still ride to the right; the strip is nowrap so it stays ONE line at 250px.
  var vxNow=LASTVEX.SPY; var vexLive = !!(vxNow && (now-vxNow.ts)<=FEED_STALE_MS);
  var stages=[]; try{ stages=pipeStages()||[]; }catch(ePS){ stages=[]; }
  var strip='';
  try{
    stages.forEach(function(sg,i){
      var extra=(sg.key==='rec') ? (' Feed is '+(feedLive?'live':'waiting')+', vex '+(vexLive?'capturing':'waiting')+'.') : '';
      var tip=(sg.tip+extra).replace(/"/g,'');
      strip+='<span data-pipe="'+sg.key+'" title="'+tip+'" style="display:inline-flex;align-items:center;white-space:nowrap">'+
        '<span style="width:5px;height:5px;border-radius:50%;display:inline-block;margin-right:2px;background:'+pipeColor(sg.state)+'"></span>'+
        sg.label+'</span>';
    });
  }catch(eST){}
  var footTip=('Where is today’s data in the pipeline? recorded → saved into the repo folder → pushed to GitHub → nightly review back. '+
    'Green = that stage happened, amber = it has not but that is expected, red = it is broken, grey = not knowable right now. Hover any stage for the detail.').replace(/"/g,'');
  var ctrls='';
  try{
    // (v15.71) THE 💾 IS A CHIP: it says whether the day is saved and, when the panel cannot save on its own, what one click fixes.
    var asv=null; try{ asv=autosaveState(); }catch(eAs){ asv=null; }
    var asCode=asv?asv.code:'idle';
    var asCol=({ saved:PAL.longAccent, pending:PAL.amber, due:'#f0616d', perm:PAL.amber })[asCode]||PAL.line;
    var asLabel='💾'+(asCode==='due'?' DUE':(asCode==='perm'?'!':''))+((asCode==='due' && asv && asv.late>0)?('+'+asv.late):'');
    var asTip=''; try{ asTip=autosaveTip(asv); }catch(eAt){ asTip='Is today’s data saved in the repo folder? Click to save now.'; }
    ctrls='<span style="display:inline-flex;gap:4px;align-items:center">'+warn+
      '<span onclick="window.__gptsRepoExport&&window.__gptsRepoExport()" data-autosave="'+asCode+'" style="cursor:pointer;border:1px solid '+asCol+';'+((asCode==='idle'||asCode==='nodata')?'':('color:'+asCol+';'))+'border-radius:6px;padding:0 3px'+(asCode==='due'?';font-weight:800':'')+'" title="'+asTip+'">'+asLabel+'</span>'+
      '<span onclick="window.__gptsRepoPick&&window.__gptsRepoPick()" style="cursor:pointer;border:1px solid '+PAL.line+';border-radius:6px;padding:0 3px" title="Pick the repo data folder once; choose “Allow on every visit” so nightly exports are silent.">📁</span>'+
      '</span>';
  }catch(eC){}
  // (v10.55 PART E) the conversion the panel is doing, on the face: 'ES/SPY 10.071 (live)'
  // when the ratio is being measured this bar, '(≈ last)' / '(≈ const)' when it is not —
  // and every converted level upstairs carries the same ≈ so the two can never disagree.
  var futTxt='';
  try{
    var ft=futRatioText();
    if(ft){
      futTxt='<span title="Every level on this panel is computed in '+FUTMODE.underlying+' strikes (that is where the options tape lives) and DISPLAYED in '+FUTMODE.chart+
        ' points through this ratio. (live) = measured from the chart price this bar. (≈ …) = the last good ratio or the constant, and then every converted number is marked ≈. Recording stays in '+
        FUTMODE.underlying+' strikes, so the learning is unaffected." style="color:'+(FUTMODE.live?PAL.blue:PAL.amber)+'">'+ft+'</span>';
    }
  }catch(eFt){}
  var evTxt='';
  try{ var el=eventTagLabel(); if(el) evTxt='<span title="Event tag set for today in ⚙ — recorded on every feature record so an event day can be separated from an ordinary one." style="color:'+PAL.gold+'">'+el+'</span>'; }catch(eEv){}
  return '<div title="'+footTip+'" style="display:flex;align-items:center;gap:5px;color:'+PAL.sub+';font-size:8px;letter-spacing:0.2px;white-space:nowrap;overflow:hidden">'+
    strip+
    futTxt+evTxt+
    ctrls+
    '<span style="margin-left:auto">v'+GPTS_VERSION+'</span>'+
  '</div>';
}

// ===== #10 ALERTS =====
// Fire on CONFIRMED state transitions only, with a per-key cooldown so an
// oscillating value cannot spam. Each event has independent on/visual/sound in
// CFG.alerts. Visual = a brief header pulse; sound = a short WebAudio beep.
var ALERT_PREV = {};                 // last seen state per tracked key
var ALERT_COOLDOWN = {};             // key -> ts of last fire
var ALERT_COOLDOWN_MS = 120000;      // 2 min per key
function beep(){
  try{
    var Ctx=window.AudioContext||window.webkitAudioContext; if(!Ctx) return;
    ALERT_AC = ALERT_AC || new Ctx();
    var o=ALERT_AC.createOscillator(), g=ALERT_AC.createGain();
    o.type='sine'; o.frequency.value=880; o.connect(g); g.connect(ALERT_AC.destination);
    g.gain.setValueAtTime(0.0001, ALERT_AC.currentTime);
    g.gain.exponentialRampToValueAtTime(0.12, ALERT_AC.currentTime+0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, ALERT_AC.currentTime+0.25);
    o.start(); o.stop(ALERT_AC.currentTime+0.26);
  }catch(e){}
}
var ALERT_AC=null;
function pulseHeader(col){
  var p=document.getElementById('gpts-grade'); var host=p?p.parentNode:null;
  if(!host) return;
  try{
    host.style.transition='box-shadow .15s';
    host.style.boxShadow='0 0 0 2px '+col+' inset';
    setTimeout(function(){ host.style.boxShadow='none'; }, 700);
  }catch(e){}
}
function fireAlert(ev, key, col, label){
  var cfg=CFG.alerts[ev]; if(!cfg || !cfg.on) return;
  var ck=ev+':'+key, now=Date.now();
  if(ALERT_COOLDOWN[ck] && (now-ALERT_COOLDOWN[ck])<ALERT_COOLDOWN_MS) return;
  ALERT_COOLDOWN[ck]=now;
  if(cfg.vis) pulseHeader(col);
  if(cfg.snd) beep();
}
function runAlerts(sym, fr){
  if(!CFG.alerts) return;
  // feed stale (state transition to red)
  var prevFeed=ALERT_PREV['feed']; ALERT_PREV['feed']=fr.state;
  if(fr.state==='red' && prevFeed && prevFeed!=='red') fireAlert('feedStale','SPY',PAL.shortAccent);
  // King roll
  var kd=kingDay(sym); var kc=kd?kd.count:0;
  var prevKC=ALERT_PREV['kingCount']; ALERT_PREV['kingCount']=kc;
  if(typeof prevKC==='number' && kc>prevKC) fireAlert('kingRoll','SPY',PAL.gold);
  // in-play node -> Accumulating, and dissipate/absorption on the in-play node
  var anc=resolveAnchor(sym);
  if(anc && anc.ok && anc.active){
    var k=anc.active.k;
    var h=nodeHistory(sym,k);
    var ft=(h&&h.length>=2)?histTrend(h, liveNodePct(sym,k)):null;
    var lbl=ft?ft.label:'Steady';
    var pk='node:'+k.toFixed(2);
    var prevLbl=ALERT_PREV[pk]; ALERT_PREV[pk]=lbl;
    if(prevLbl && prevLbl!=='Building' && lbl==='Building') fireAlert('inplayAccum',k.toFixed(2),PAL.longAccent);
    if(prevLbl && prevLbl!=='Fading' && lbl==='Fading') fireAlert('dissipate',k.toFixed(2),PAL.shortAccent);
    var ab=absorptionAt(sym,k);
    var pkA='absorb:'+k.toFixed(2); var prevAb=ALERT_PREV[pkA]; ALERT_PREV[pkA]=ab?1:0;
    if(ab && !prevAb) fireAlert('absorption',k.toFixed(2),(anc.active.k>=STATE[sym].price?PAL.shortAccent:PAL.longAccent));
  }
  // trap read forms/flips
  var rel=relativeRead(sym);
  if(rel){ var prevRel=ALERT_PREV['trap']; ALERT_PREV['trap']=rel.cls;
    if(prevRel && prevRel!==rel.cls && (rel.cls==='trap'||rel.cls==='long')) fireAlert('trap','SPY',(rel.cls==='trap'?PAL.shortAccent:PAL.longAccent)); }
}

// ===== CONFLUENCE ENGINE (v10.13) =====
// Integrates the four independent reads into ONE directional thesis + an aligned
// count, so the panel tells a single coherent story instead of four scattered
// readouts. Four contributors, each votes -1 (bearish) / +1 (bullish) / 0:
//   \u2460 LEAN    (King)  \u2014 kingVerdict().dir. The structural anchor. weight 1.2
//   \u2461 TRIGGER (Price) \u2014 trendVerdict state + live BO/short setup. price must
//                        confirm the move. weight 1.2
//   \u2462 CONTEXT (Board) \u2014 netPositioning().dir. net board tilt. weight 0.8
//   \u2463 BREADTH (Nodes) \u2014 MULTI-NODE: counts building resistance overhead &
//                        dissipating support below (bearish) vs building support
//                        below & dissipating resistance above (bullish). One node
//                        is weak; several agreeing across strikes is strong.
//                        weight scales with how many nodes agree (up to 1.2).
// Thesis declares a direction only at >=3/4 contributors aligned (weighted);
// otherwise "Mixed / No edge" \u2014 a confluence tool earns trust by staying quiet.
function nodeBreadth(sym){
  // Aggregate ALL nearby nodes into a directional node-bias.
  var fs=futureStructureSummary(sym);
  var above=fs.above||[], below=fs.below||[];
  function isBuild(r){ return r.state && r.state.label==='Building'; }
  function isFade(r){ return r.state && r.state.label==='Fading'; }
  // Bearish node evidence: resistance building overhead + support dissipating below.
  var resBuild=0, supFade=0;
  // Bullish node evidence: support building below + resistance dissipating overhead.
  var supBuild=0, resFade=0;
  above.forEach(function(r){ if(isBuild(r)) resBuild++; else if(isFade(r)) resFade++; });
  below.forEach(function(r){ if(isBuild(r)) supBuild++; else if(isFade(r)) supFade++; });
  var bearScore = resBuild + supFade;   // things pushing price DOWN
  var bullScore = supBuild + resFade;   // things pushing price UP
  var net = bullScore - bearScore;
  var dir = net>0?1:(net<0?-1:0);
  // magnitude 0..1: how lopsided, capped so 3+ agreeing nodes = ~full weight
  var mag = Math.min(1, Math.abs(net)/3);
  return { dir:dir, mag:mag, resBuild:resBuild, supFade:supFade, supBuild:supBuild,
           resFade:resFade, bearScore:bearScore, bullScore:bullScore, net:net };
}
function confluence(sym){
  sym=sym||'SPY';
  var S=STATE[sym]||{};
  var px=S.price;
  // \u2460 LEAN \u2014 King
  var kd=kingDay(sym); var mv=(kd&&kd.moves)?kd.moves:[];
  var tp=tapeMap(sym); var kingK=(tp&&typeof tp.king==='number')?tp.king:null;
  var kv=kingVerdict(mv, kingK, px, Date.now());
  var lean = kv.dir;                                   // -1/0/+1
  // \u2461 TRIGGER \u2014 price trend + live directional setup
  var tv=trendVerdict(sym);
  var trendDir = tv.state==='up'?1:(tv.state==='dn'?-1:0);
  var bias=signalBias(sym);
  var setupDir = (bias.short && !bias.long)?-1:((bias.long && !bias.short)?1:0);
  // price vote: trend, escalated when a live setup agrees; setup alone if flat
  var trigger = trendDir!==0 ? trendDir : setupDir;
  var triggerStrong = (trendDir!==0 && setupDir===trendDir);
  // \u2462 CONTEXT \u2014 board tilt
  var np=netPositioning(sym);
  var board = (np && np.bias!=='balanced') ? np.dir : 0;
  // \u2463 BREADTH \u2014 the S/R BATTLE (v10.14). Dissipation-dominant force model:
  // support-dominant => bull(+1), resistance-dominant => bear(-1). This replaces
  // the crude Building/Fading count for the confluence vote so the whole stack
  // reads the same battle the S/R Bias bar shows. nodeBreadth kept as magnitude.
  var srb=srBattle(sym);
  var nb=nodeBreadth(sym);
  var nodes = srb ? (srb.dom==='support'?1:(srb.dom==='resistance'?-1:0)) : nb.dir;
  // a fresh crossover intensifies the breadth weight (the tradeable moment)
  var breadthMag = srb ? (srb.cross?1.0:0.75) : (0.4+0.6*nb.mag);
  // ---- Weighted vote ----
  var W={ lean:1.2, trigger:1.2, board:0.8, nodes:1.2 };
  var contribs=[
    { key:'lean',    role:'LEAN',    dir:lean,    w:W.lean },
    { key:'trigger', role:'TRIGGER', dir:trigger, w:W.trigger*(triggerStrong?1.15:1) },
    { key:'board',   role:'CONTEXT', dir:board,   w:W.board },
    { key:'nodes',   role:'BREADTH', dir:nodes,   w:W.nodes*breadthMag }
  ];
  var score=0, bull=0, bear=0, voting=0;
  contribs.forEach(function(c){ score+=c.dir*c.w; if(c.dir>0){bull++;voting++;} else if(c.dir<0){bear++;voting++;} });
  // Thesis direction = sign of weighted score; require >=3 of 4 on that side.
  var dir = score>0?1:(score<0?-1:0);
  var agree = dir>0?bull:(dir<0?bear:0);
  var declared = (dir!==0 && agree>=3);
  var thesisDir = declared ? dir : 0;
  var word = thesisDir>0?'BULLISH':(thesisDir<0?'BEARISH':'MIXED / NO EDGE');
  return { dir:thesisDir, declared:declared, word:word, score:score,
           aligned:agree, voting:4, bull:bull, bear:bear,
           contribs:contribs, kv:kv, nb:nb, np:np, tv:tv, bias:bias,
           kingK:kingK, px:px };
}


// ============================================================================
