var ARCH_VIEW=false, ROADMAP_VIEW=false, ITEMS_VIEW=false, LEARN_VIEW=false, REC_VIEW=false;   // (v15.59) ⚙ Architecture · 🗺 Roadmap · (v15.60) 📌 Open Items · (v15.62) 📚 Learn · (v15.70) 💡 Rec
