// (v15.60) 📌 Open Items — issues and questions, with a field to add them; enhancement requests live on the Roadmap tab
window.__gptsDebug.showItems=function(b){ ITEMS_VIEW=(b!==false); if(ITEMS_VIEW){ ANALYSIS_VIEW=false; TESTING_VIEW=false; ARCH_VIEW=false; ROADMAP_VIEW=false; LEARN_VIEW=false; REC_VIEW=false; } if(typeof render==='function') render(); };
window.__gptsDebug.learn=function(){ return { doc:learnLoad(), gauge:learnGauge(learnLoad()) }; };
