function futBarsHealth(){
  try{
    var o=futBarsLoad(); if(!o) return { ok:false, why:'no courier data (is the companion running?)' };
    var mk=[], k, ageMin=null;
    for(k in o){ if(k.charAt(0)==='_') continue;
      var m=o[k]; if(!m) continue;
      mk.push({ k:k, n:(m.rows?m.rows.length:0), err:m.err||null, at:m.at||null });
    }
    if(o._at) ageMin=Math.round((Date.now()-o._at)/60000);
    return { ok:mk.length>0, markets:mk, ageMin:ageMin, trimmed:!!o._trimmed };
  }catch(e){ return { ok:false, why:'threw: '+(e&&e.message||e) }; }
}
var HLBASE_KEY='gpts_hodlod_base_v1';
// ⚖ hand-set: the baked-in base stands on 284 sessions; do not swap it for less.
// ⚠ KEEP THESE DECLARATIONS BARE - the test harness's val() reads a constant up to the first
// `;` followed by a NEWLINE, so a trailing comment on this line silently captures half the file.
var HLBASE_MIN_SESSIONS=120;
// ⚖ hand-set: a rung with a tiny n is a number, not a rate.
var HLBASE_MIN_BUCKET=50;
function hlBaseNormalise(j){
  try{
    if(!j || !j.corpus || !(j.corpus.sessions>0)) return null;
    var L=j.ladder && j.ladder.both; if(!L) return null;
    var out=[], ws=Object.keys(L).map(Number).sort(function(a,b){ return a-b; }), i, R;
    for(i=0;i<ws.length;i++){
      R=L[String(ws[i])];
      if(!R || !(R.n>0) || typeof R.rate!=='number') return null;
      out.push({ w:ws[i], rate:R.rate, n:R.n, held:R.held });
    }
    if(out.length<2) return null;
    // ⚠⚠ A SMALL CORPUS PASSES EVERY OTHER CHECK AND IS STILL WRONG. Caught while building this:
    // TWO synthetic sessions produced ladder rates 57/80/100/100/100 - monotone, well-formed, and
    // complete nonsense. Monotonicity does not imply evidence. The baked-in fallback stands on 284
    // sessions, so a courier payload must clear a floor before it is allowed to REPLACE it.
    if(!(j.corpus.sessions>=HLBASE_MIN_SESSIONS)) return null;
    for(i=0;i<out.length;i++) if(!(out[i].n>=HLBASE_MIN_BUCKET)) return null;
    // THE LADDER'S ONE CLAIM IS THAT IT RISES. If a re-derived corpus ever produces a non-monotone
    // ladder, the section's only predictive statement is unsupported and the payload is REFUSED
    // rather than drawn - the same gate test_hodlod applies to the baked-in rates.
    for(i=1;i<out.length;i++) if(out[i].rate<out[i-1].rate) return null;
    var E=j.expected||{}, S=j.sequence||{};
    // (v14.60) the wick family rides through with its OWN n, because it is averaged over a
    // DIFFERENT set of sessions than the ladder: no-wick days and Tukey outliers are excluded per
    // the operator's rule. A shared n would overstate what these medians stand on.
    var W=(j.wickFamily && j.wickFamily.median) ? j.wickFamily.median : null;
    return { n:j.corpus.sessions, first:j.corpus.first, last:j.corpus.last, ladder:out,
             wick: W ? { wick:W.wick, bop:W.bop, mud:W.mud, wickPct:W.wick_pct,
                         wickMed:W.wick_median, bopMed:W.bop_median, mudMed:W.mud_median,
                         wickPctMed:W.wick_pct_median,
                         wick_n:W.wick_n, bop_n:W.bop_n, mud_n:W.mud_n, wickPct_n:W.wick_pct_n,
                         excluded:(j.wickFamily||{}).excluded||null } : {},
             tookMin:E.took_min, gapMin:E.gap_min, rngPts:E.rng_pts, rngUsd:E.rng_usd,
             medTook:(E.median_for_contrast||{}).took_min, medGap:(E.median_for_contrast||{}).gap_min,
             medRng:(E.median_for_contrast||{}).rng_pts,
             rngP25:E.rng_p25, rngP75:E.rng_p75,
             firstClock:E.first_clock, secondClock:E.second_clock,
             lodFirstPct:S.pct_LOD_first };
  }catch(e){ return null; }
}
function hodlodBase(){
  try{
    var raw=null; try{ raw=JSON.parse(localStorage.getItem(HLBASE_KEY)||'null'); }catch(e0){}
    if(raw && raw.base){
      var N=hlBaseNormalise(raw.base);
      if(N){ N.src='courier'; N.at=raw.at||null; return N; }
    }
  }catch(e){}
  var B={}; for(var k in HODLOD_BASE) B[k]=HODLOD_BASE[k];
  B.src='baked'; B.at=null;
  return B;
}
// ============================================================================================
// (v14.64) HAS THE LOW / HIGH OF DAY ALREADY PRINTED?
//
// The operator's requirement, verbatim 2026-08-28: "i just want to know with high accuracy whether
// the hod or lod have occurred ... I want to know it as early as possible."
//
// ⚠⚠ THIS IS A TABLE, NOT A MODEL, AND THAT IS A DELIBERATE DOWNGRADE. A 5-feature logistic was
// built first and then measured against a plain two-way lookup:
//     lookup posr x time     AUC 0.8787   Brier 0.1321
//     logistic, 5 features   AUC 0.8795   Brier 0.1321
// Identical Brier, 0.0008 of AUC. The regression was ceremony. The table wins on everything that is
// not AUC: every cell carries its own n, the operator can READ it and argue with it, and drift shows
// up as a cell that stops matching. Five coefficients cannot be argued with. See FINDINGS F-4.
// ⚠ Adding a third axis (`stood`) made it WORSE - 0.8729 - because the cells go thin. Two axes.
//
// THE TWO AXES, and why these two:
//   posr  = (price - extreme) / (session range so far). How far price has travelled AWAY from the
//           extreme. Alone it scores AUC 0.829 - better than the entire clock baseline (0.820).
//   mins  = minutes since the RTH open. The base rate rises from ~40% at 09:30 to ~64% by noon all
//           on its own, so time is IN the table rather than something the table gets credit for.
//
// ⚠ WHAT IS DELIBERATELY NOT IN IT, each measured and rejected (FINDINGS F-1/F-2/F-3):
//   IB30 / IB60 (AUC 0.684 / 0.655)   - crude switches approximating posr (0.829)
//   the 50-SMA (0.713), open reclaimed (0.709), 60-minute breakout (0.501)
//   sweep + reclaim (0.559)           - 48% standalone, BELOW its own base rate
//   momentum divergence (0.545) and NQ cross-market divergence (-0.0014 AUC)
//   ⚠ Both divergences only LOOK anti-predictive: they can fire ONLY at the instant a fresh extreme
//     prints, which is exactly posr~0 - a state the table already reads. See F-3.
//
// ⚠ PROVISIONAL. 284 sessions of EPM26 1-minute, 2025-06-02 -> 2026-08-21. ONE instrument, ONE
// 15-month regime, and NO forward test. It is enrolled in FEATURES from its first line so the live
// rate accumulates honestly beside the backtest.
// ⚠ THESE ARE TWO DIFFERENT NUMBERS AND CONFUSING THEM WOULD BE THIS PROJECT'S OLDEST MISTAKE.
// `thresh`/`notIn` are CELL probabilities - what the table says at this instant.
// `inHit`/`notInHit` are DECISION accuracies - how often the call was right the FIRST time it
// crossed, one row per session, which is the only n a trader can act on. The face shows the cell;
// the hover shows the decision. Both measured on the FIRST-PRINTED extreme, which is what ⓪a calls.
// ⚠ THESE ARE TWO DIFFERENT NUMBERS AND CONFUSING THEM WOULD BE THIS PROJECT'S OLDEST MISTAKE.
// `thresh`/`notIn` are CELL probabilities - what the table says at this instant.
// `inHit`/`notInHit` are DECISION accuracies - how often the call was right the FIRST time it
// crossed, one row per session, on the FIRST-PRINTED extreme, which is what ⓪ a calls.
//
// ⚠⚠ (v14.70) THE TABLE NOW COVERS THE WHOLE SESSION. It previously skipped the first 60 minutes of
// every day because the study required IB60 to exist before scoring a row. IB60 was then MEASURED
// AS WORTHLESS (AUC 0.655, adds nothing once posr is known) and dropped from the model - but the
// exclusion stayed behind, leaving the 08:30 column empty and the panel saying "thin cell, n=0" for
// the first 45 minutes of every session. Re-derived from minute 5: 72 of 72 cells populated,
// 44,302 observations. ⚠ Verified strictly additive - AUC on the SAME late-session rows is
// IDENTICAL (0.8787), so nothing that already worked was traded away.
// ⚠ AND THE NOT-IN CALL LIVED IN THE MISSING CELLS: 72% on n=85 became 85% on n=230, and it fires
// at 08:40 instead of 09:45. A leftover constraint from a deleted feature was costing the better
// half of the feature.
// ⚠⚠ (v14.84) `inHit` WAS 92 AND THE HONEST NUMBER IS 63. FINDINGS F-12, confirmed by three
// independent reproductions (`tools/study-second.py`), open since 2026-08-28:
//     the panel, live   calls whichever extreme is FIRST-PRINTED AT THAT MOMENT   -> 63%, n=284
//     the study behind 92   selected the side that TURNED OUT to print first      -> 91%, n=284
// Selecting the side with hindsight conditions on the answer. When a standing low breaks at 11:00
// the live panel had already made the call and was wrong; the backtest silently re-picked. 92 was
// never a rate this panel could earn — it was the rate of a decision made after the fact.
// ⚠ THE CELL RATES IN HLTAB ARE UNAFFECTED. They are a lookup of what happened, not a decision, and
// their AUC 0.879 stands. Only the DECISION accuracy quoted in the hover was wrong.
var HLTAB_META={ sessions:284, obs:44302, first:'2025-06-02', last:'2026-08-21', binMin:45, minBar:5,
                 thresh:70,   inHit:63,    inN:284,   inCT:'9:20',   inHindsight:92,
                 notIn:20,    notInHit:85, notInN:230, notInCT:'8:40',
                 secondMed:'13:29', secondQ1:'11:48', secondQ3:'14:45', secondAhead:99 };
// rows = posr octile (0 = on the extreme, 7 = the far side); cols = 45-minute blocks from 08:30 CT.
// each cell is [n, percent] and a cell under 25 observations is null - it REFUSES rather than guesses.
var HLTAB=[
    [[740,4],[819,7],[881,8],[902,9],[855,12],[923,15],[922,20],[899,28],[604,47]],
    [[598,10],[655,18],[687,21],[635,33],[676,36],[627,39],[560,57],[569,66],[516,84]],
    [[507,16],[566,26],[542,34],[551,49],[572,56],[542,65],[519,68],[534,84],[441,96]],
    [[411,22],[503,33],[441,50],[462,55],[450,65],[456,78],[546,85],[544,95],[425,99]],
    [[440,27],[523,45],[444,62],[473,67],[452,73],[466,81],[563,91],[560,97],[425,100]],
    [[492,32],[566,58],[533,72],[543,75],[573,84],[537,88],[517,95],[532,98],[441,100]],
    [[604,40],[656,59],[700,76],[642,86],[675,89],[632,95],[557,98],[569,99],[519,100]],
    [[752,47],[824,74],[884,84],[904,90],[859,96],[927,99],[928,99],[905,100],[605,100]]
  ];
function hlCell(posr, mins){
  try{
    if(typeof posr!=='number' || typeof mins!=='number') return null;
    var pi=Math.max(0,Math.min(HLTAB.length-1, Math.floor(posr*HLTAB.length)));
    var ti=Math.max(0,Math.min(HLTAB[0].length-1, Math.floor(mins/HLTAB_META.binMin)));
    var c=HLTAB[pi][ti];
    if(!c || c[1]==null) return { p:null, n:(c?c[0]:0), pi:pi, ti:ti, why:'too few samples in this cell' };
    return { p:c[1], n:c[0], pi:pi, ti:ti };
  }catch(e){ return null; }
}
// THE CALL. Descriptive only - it says how often an extreme in this state was the day's, never what
// price will do. `left` is how much of the session range still lies between price and the far side,
// which is the honest companion to the probability: F-5 measured that at the 70% call HALF the range
// is still ahead and price travelled a median 30% of it.
// ⚠ EXTRACTED SO IT CAN BE EXECUTED IN A TEST. While this lived inline in secDay(), the only way
// to check it was to grep the render source for the word "NOT IN" - and a mutation proved that
// assertion passed against a DEAD branch. A grep cannot tell a live branch from a dead one; running
// the function can. Failure pattern #8, caught by mutation rather than by review.
//
// THREE STATES, NOT TWO. "STANDING" is the honest middle: the table has an opinion but not a
// confident one, and collapsing 45% into either call would overstate what it knows.
function hlVerdict(D, CALL, T){
  try{
    if(CALL && CALL.p!=null){
      // (v14.86) no em-dash between the state and its number — "HOD IN 100%", his wording.
      if(CALL.notIn) return D.first+' NOT IN '+(100-CALL.p)+'%';
      return D.first+(CALL.in?' IN ':' STANDING ')+CALL.p+'%';
    }
    if(CALL) return D.first+' STANDING — no rate (thin cell, n='+CALL.n+')';
    return T ? (D.first+' IN '+T.rate+'%') : (D.first+' STANDING — too early to rate');
  }catch(e){ return (D&&D.first?D.first:'')+' —'; }
}
// (v14.72) THE "% OF THE RANGE" CLAUSE - GATED AND RENAMED, because it was claiming something it
// never measured. `far` is 1 - posr: the distance from price to the OTHER END OF THE RANGE PRINTED
// SO FAR, on the running range. It is not a forecast of travel, and it printed as "% of the range
// still ahead" even on days BOTH extremes were already in - on the same line that says "the range
// is set". The operator caught it: "the 1% of the range still ahead seems to imply that we are at
// the top". The arithmetic was right and the LABEL was wrong: failure pattern #1, a value shown
// under a label implying a different claim, with nothing throwing.
// ⚠ The gate is the SAME directly observable fact the "toward HOD" clause has used since v14.66
// (D.secondT > D.clock). One fact, one gate, two clauses - they can never disagree again.
// ⚠ EXTRACTED SO A TEST CAN EXECUTE IT. Its predecessor was covered by a grep of the render source
// for "still ahead", which passed against a clause that fired in the wrong state - L-O / failure
// pattern #8. Running the function is the only assertion that can fail for the right reason.
function hlFarClause(D, CALL){
  try{
    if(!D || !CALL || CALL.far==null) return '';
    // ⚠⚠ (v15.22) THE SAME DEAD GATE, THIRD INSTANCE. `D.secondT > D.clock` is false from the third
    // bar of every session — a session has a running high and a running low almost immediately — so
    // this clause has never once rendered since v14.72, and neither had the far-side line it was
    // written to agree with. One wrong idea about what `secondT` means disabled three clauses.
    // The condition it MEANT to express is "the far side is still being made", and the table's IN
    // call is the panel's own statement of exactly that, printed on the same line.
    if(!(CALL.in===true)) return '';
    return ' \u00b7 <b>'+Math.round(100*CALL.far)+'% of the range to today\u2019s '+D.second+' so far</b>';
  }catch(e){ return ''; }
}
function lodhodCall(D){
  try{
    if(!D || !D.ok || D.posr==null) return null;
    var c=hlCell(D.posr, (D.clock-(mul(8,3600)+mul(30,60)))/60);
    if(!c) return null;
    // ⚠ THE FIELD IS `far`, AND IT WAS `left` FOR ONE COMMIT. The render and the test both read
    // CALL.far, so the "% still ahead" figure silently never drew. Caught by t14 executing the
    // function rather than grepping it - a grep would have found `left` and been satisfied.
    var out={ p:c.p, n:c.n, cell:c, first:D.first, in:false, far:null };
    if(D.far!=null) out.far=Math.max(0, Math.min(1, D.far));
    out.in = (c.p!=null && c.p>=HLTAB_META.thresh);
    // ⚠ THE OTHER HALF, AND IT IS WEAKER THAN THE FIRST - SAY SO. At P<=20% the extreme was broken
    // 72% of the time (n=85, median 09:45) against a ~57% base at that hour. Real, early, and thin.
    // An earlier pass measured 93% here; that number came from a sample that also asked about the
    // SECOND extreme, which is a different and easier question. Restricted to what ⓪a actually
    // calls it is 72%. Do not quote the 93%.
    out.notIn = (c.p!=null && c.p<=HLTAB_META.notIn);
    return out;
  }catch(e){ return null; }
}

// ============================================================================================
// (v14.72) THE FAR SIDE — WHERE THE OTHER EXTREMITY CAN GET TO, HOW LIKELY, AND WHEN
//
// The operator's requirement, 2026-08-28, verbatim: "i want it to say something like LOD IN -74%,
// HOD expected around 7772-7792 in 3.5 Hrs between 1:30pm and 2pm - 80%", then, after the numbers
// came back: "the probability is very low when predicting the other side ... what data points would
// allow you to predict this better".
//
// ⚠⚠ WHAT WAS MEASURED AND WHY THIS IS SHAPED THE WAY IT IS — FINDINGS F-13, F-14, F-15, F-16.
//   · Predicting the far side's PRICE directly is a dead end: a fixed 1.36x expansion beats a
//     10-feature gradient boosting model (9.2 vs 9.9 ES points of median error). F-13.
//   · Predicting its CLOCK is worse: the clock alone beats every factor set tried. F-13.
//   · Re-posed as "will price REACH this level before the close", the same data gives
//     AUC 0.826, calibrated at every decile, and HALF of all readings land in a <=20% bucket that
//     is right 92% of the time. F-14. That is the model this block ships.
//   · Re-posed as "GIVEN it reaches the level, when", timing becomes predictable too - and the
//     analytic first-passage law T ~ (distance/sigma)^2 does 95% of the work of the ML model. F-15.
//   · Daily ATR adds nothing (the realized sigma already contains it) and level IDENTITY - prior
//     day high/low/close, overnight extremes - adds nothing once distance is properly controlled.
//     ⚠ A SPARSE CONTROL SAID +12 POINTS AND IT WAS A PHANTOM. F-16.
//
// ⚠ SO THE HONEST CLAIM IS NARROW: this says how often a level LIKE THIS ONE, at this distance,
// with this much session left, has been traded. It never says price WILL go there, and the timing
// is a RANGE because the median error is 42 minutes on an 86-minute horizon.
//
// ⚠ THE 80% TIME CLAIM IS A ONE-SIDED FLOOR, NOT A BOX. Measured: a 30-minute box around the
// median is worth 15% and an hour is worth 24%; to reach 80% a two-sided window has to be 3.6
// HOURS wide. So the face states the floor ("not before X") at 80% and the middle-half window at
// its true 50%. Printing "3-3.5h, 80%" would be a lie of precision.
var FARSIDE_KEY='gpts_farside_v1';
