    var RB=emRailBounds(EB, RAILPS, (function(){ try{
      var b=sessionBody(sym); if(!b || !(EB.emRr>0)) return null;
      return { hi:b.hi*EB.emRr, lo:b.lo*EB.emRr, open:b.open*EB.emRr, close:b.close*EB.emRr };
    }catch(eRB){ return null; } })());
