window.__gptsDebug.futBars=function(){ try{ return futBarsHealth(); }catch(e){ return 'threw: '+e.message; } };
window.__gptsDebug.tape=function(){ try{ return tapeHealth(); }catch(e){ return 'threw: '+e.message; } };            // (v15.66) bars per book today, the last write
